	/**
	 * Default Constructor
	 */
    public CarePlanService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CarePlanEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CarePlanRepository.class) );
		this.validator		= applicationContext.getBean(CarePlanValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CarePlan
	 */
		public CarePlan createCarePlan( CreateCarePlanCommand command ) {

		CarePlan entity = new CarePlan();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCarePlanId( command.getCarePlanId() );
            entity.setPlanNumber( command.getPlanNumber() );
            entity.setGoalSummary( command.getGoalSummary() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CarePlan {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCarePlanCommand
	 * @return		CarePlan
	 */
	public CarePlan updateCarePlan( UpdateCarePlanCommand command ) {

		CarePlan entity = new CarePlan();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCarePlanId( command.getCarePlanId() );
            entity.setPlanNumber( command.getPlanNumber() );
            entity.setGoalSummary( command.getGoalSummary() );
            entity.setPatient( command.getPatient() );
            entity.setEncounters( command.getEncounters() );
            entity.setTasks( command.getTasks() );
            entity.setCareTeam( command.getCareTeam() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of CarePlan {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCarePlanCommand
	 */
	public void delete( DeleteCarePlanCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCarePlanId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of CarePlan {0} ", id );

	}

	/**
	 * Method to retrieve the CarePlan via CarePlanFetchOneSummary
	 * @param 	summary CarePlanFetchOneSummary
	 * @return 	CarePlanFetchOneResponse
	 */
	public CarePlan getCarePlan( CarePlanFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CarePlanFetchOneSummary arg cannot be null" );

		CarePlan entity = null;
		UUID id = summary.getCarePlanId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a CarePlan using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all CarePlans
	 *
	 * @return 	List<CarePlan>
	 */
    public List<CarePlan> getAllCarePlan() {
		List<CarePlan> list = projector.findAll( new FindAllCarePlanQuery() );
		return list;
	}

